#!/usr/bin/env bash
# User-scope lz-tdd rules A/B. Usage: run-ab.sh [--dry-run] <arm a|b> <k> [<arm> <k> ...]
# arm a = packaged lz-tdd only; arm b = same + the Test-first rule folder generated by ../slim-arms.sh.
# Long paths only: run-slim refuses reads through 8.3 short paths.
here="$(cygpath -m "$(cd "$(dirname "$0")" && pwd)")"
. "$here/../slim-arms.sh"
ALLOW='Skill Read Edit Write Glob Grep Bash(npm test*) Bash(npm run test*) Bash(npx vitest*) Bash(npx tsc*) Bash(ls *) Bash(cat *)'
DENY='Skill(lars-mode) Skill(lz.windows:deny-bash-commands) Skill(lz.windows:reset-bash-commands) WebFetch WebSearch'
dry=()

if [ "${1:-}" = --dry-run ]; then
  dry=(--dry-run)
  shift
fi

ensure_pkg || exit 1
ensure_rules_b || exit 1
mkdir -p "$here/out"

while [ $# -ge 2 ]; do
  arm=$1 k=$2
  shift 2
  # Outside the home folder: a cwd under it loads ~/.claude/CLAUDE.md as project instructions.
  dir="$slim_root/rules-ab/runs/$arm-$k"
  rm -rf "$dir" "$dir".*
  mkdir -p "$dir/src"
  cp -r "$here/template/." "$dir/"
  (cd "$dir" && npm ci --prefer-offline --no-audit --no-fund --silent) || { echo "== $arm $k npm ci failed"; continue; }

  if [ "$arm" = b ]; then
    rules="$rules_b"
  else
    rules=none
  fi

  node "$HOME/.claude/references/slim-claude-p/run-slim.ts" --cwd "$dir" --prompt-file "$here/task.md" \
    --out "$here/out/run-$arm-$k.json" --plugin-dir "$pkg_dir" --rules "$rules" --model opus --timeout-min 25 \
    --allow "$ALLOW" --deny "$DENY" "${dry[@]}"
  status=$?
  echo "== $arm $k exit=$status"

  # A spend-limit hit fails in seconds; stop the queue rather than turn one failure into many.
  if [ "$status" -ne 0 ]; then
    echo "[ERROR] stopping the queue after $arm $k"
    exit 1
  fi
done
